CREATE TABLE IF NOT EXISTS `${PROJECT_ID}.${DATASET}.documents` (document_id STRING NOT NULL, case_id STRING NOT NULL, document_type STRING, mime_type STRING, checksum_sha256 STRING, processing_status STRING, confidence FLOAT64, uploaded_at TIMESTAMP, processed_at TIMESTAMP) PARTITION BY DATE(uploaded_at) CLUSTER BY case_id,processing_status;
CREATE TABLE IF NOT EXISTS `${PROJECT_ID}.${DATASET}.document_extractions` (extraction_id STRING NOT NULL, document_id STRING NOT NULL, case_id STRING NOT NULL, field_name STRING, value_hash STRING, confidence FLOAT64, page_number INT64, extractor STRING, extractor_version STRING, review_status STRING, created_at TIMESTAMP) PARTITION BY DATE(created_at) CLUSTER BY case_id,review_status;
